<!--
 * @file form.vue
 * @description DemoItem 表单弹窗（由 fw gen crud 生成）：独立于列表页的录入 / 编辑组件，
 *   字段与控件由 schema 元信息推导（input / textarea / number / switch / datetime / dict-select / select）。
 *   提交走 api/demo-item.ts；外键下拉数据源与枚举字典按 TODO 补齐后即可端到端使用。
 * @author donttemo
 * @created 2026-10-13
 * @module admin-web/views
 * @since v0.1.0
 * @generated by @fw/cli gen crud —— 本文件由代码生成器产出；业务扩展请勿直接修改，改用继承 / 钩子（--force 才会覆盖本文件）
-->

<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue';
import { ElMessage } from 'element-plus';
import type { FormInstance, FormRules } from 'element-plus';
import * as demoItemApi from '@/api/demo-item';
import type { CreateDemoItemInput, UpdateDemoItemInput } from '@/api/demo-item';
import type { FormField } from '@/components/CrudTable/types';

const props = defineProps<{
  /** 弹窗可见性（v-model 语法糖） */
  modelValue: boolean;
  /** 编辑目标 ID；缺省为新建 */
  demoItemId?: string;
}>();

const emit = defineEmits<{
  (event: 'update:modelValue', value: boolean): void;
  (event: 'saved'): void;
}>();

const visible = computed({
  get: () => props.modelValue,
  set: (value: boolean) => emit('update:modelValue', value),
});

const isEdit = computed(() => Boolean(props.demoItemId));
const submitting = ref(false);
const formRef = ref<FormInstance>();

/** 空表单模型（字段与后端 Create 输入对齐） */
function emptyForm(): Record<string, unknown> {
  return {
    title: undefined,
    done: undefined,

  };
}

const form = reactive<Record<string, unknown>>(emptyForm());

/** 表单字段配置（与列表页同源） */
const formFields: FormField[] = [
  { prop: 'title', label: 'title', type: 'input', rules: [{ required: true, message: '请输入title', trigger: 'blur' }] },
  { prop: 'done', label: 'done', type: 'switch' },
];

/** 必填校验规则（由字段配置推导） */
const rules = computed<FormRules>(() => {
  const result: FormRules = {};
  for (const field of formFields) {
    if (field.rules?.length) result[field.prop] = field.rules;
  }
  return result;
});

// 打开弹窗时加载详情（编辑）或重置为空表单（新建）
watch(
  () => props.modelValue,
  async (open) => {
    if (!open) return;
    Object.assign(form, emptyForm());
    if (props.demoItemId) {
      try {
        const detail = await demoItemApi.fetchDemoItem(props.demoItemId);
        Object.assign(form, detail);
      } catch {
        ElMessage.error('详情加载失败');
      }
    }
  },
);

async function submit(): Promise<void> {
  await formRef.value?.validate();
  submitting.value = true;
  try {
    if (props.demoItemId) {
      await demoItemApi.updateDemoItem(props.demoItemId, form as unknown as UpdateDemoItemInput);
    } else {
      await demoItemApi.createDemoItem(form as unknown as CreateDemoItemInput);
    }
    ElMessage.success(isEdit.value ? '已保存' : '已创建');
    visible.value = false;
    emit('saved');
  } finally {
    submitting.value = false;
  }
}
</script>

<template>
  <el-dialog v-model="visible" :title="isEdit ? '编辑 DemoItem' : '新建 DemoItem'" width="560px">
    <el-form ref="formRef" :model="form" :rules="rules" label-width="96px">
      <el-form-item
        v-for="field in formFields"
        :key="field.prop"
        :prop="field.prop"
        :label="field.label"
      >
        <el-input v-if="field.type === 'input'" v-model="form[field.prop]" :placeholder="field.placeholder ?? '请输入' + field.label" />
        <el-input v-else-if="field.type === 'textarea'" v-model="form[field.prop]" type="textarea" :rows="3" />
        <el-input-number v-else-if="field.type === 'number'" v-model="form[field.prop]" />
        <el-switch v-else-if="field.type === 'switch'" v-model="form[field.prop]" />
        <el-date-picker
          v-else-if="field.type === 'datetime'"
          v-model="form[field.prop]"
          type="datetime"
          value-format="YYYY-MM-DDTHH:mm:ss"
        />
        <el-select v-else-if="field.type === 'select' || field.type === 'dict-select'" v-model="form[field.prop]">
          <el-option v-for="option in field.options ?? []" :key="String(option.value)" :label="option.label" :value="option.value" />
        </el-select>
        <el-input v-else v-model="form[field.prop]" />
      </el-form-item>
    </el-form>
    <template #footer>
      <el-button @click="visible = false">取消</el-button>
      <el-button type="primary" :loading="submitting" @click="submit">保存</el-button>
    </template>
  </el-dialog>
</template>
